On the `with_raw_response` path this wrapper is only built on `parse()`, so `suspend()` runs wherever the caller parses. If that's inside a caller span, the inference span is left current after the stream is drained and the span has ended. On main the same flow ends with the context restored, since `stop()` detaches. The span is also still current between `create()` and `parse()`.

Would it work to suspend in `wrap_stream_result` (or right before `traced_method` returns) so both paths are covered? Same applies to `_ResponseStreamMixin`. Both tests below fail on this branch; the second passes on main:

```python
from openai import Stream

from opentelemetry import context
from opentelemetry.instrumentation.genai.openai._raw_response import (
    wrap_stream_result,
)
from opentelemetry.instrumentation.genai.openai.chat_wrappers import (
    ChatStreamWrapper,
)
from opentelemetry.util.genai.handler import TelemetryHandler

from .test_raw_response_proxy import _RawResponse


class _EmptyStream(Stream):
    def __init__(self):
        pass

    def __iter__(self):
        return iter(())

    def close(self):
        pass


def _start(tracer_provider):
    return TelemetryHandler(tracer_provider=tracer_provider).inference(
        "openai", request_model="m"
    )


def test_raw_response_span_not_current_after_create(tracer_provider):
    before = context.get_current()
    wrap_stream_result(
        ChatStreamWrapper, _RawResponse(_EmptyStream()), _start(tracer_provider), False
    )
    assert context.get_current() is before


def test_raw_response_parse_under_caller_span_then_drain(
    tracer_provider, span_exporter
):
    before = context.get_current()
    raw = wrap_stream_result(
        ChatStreamWrapper, _RawResponse(_EmptyStream()), _start(tracer_provider), False
    )
    with tracer_provider.get_tracer("t").start_as_current_span("caller"):
        stream = raw.parse()
    assert list(stream) == []
    assert len(span_exporter.get_finished_spans()) == 2
    assert context.get_current() is before
```
